def remove_duplicate_letters_brute(s):
    distinct = sorted(set(s))
    n = len(distinct)
    best = [None]

    def helper(idx_in_s, chosen, remaining):
        if not remaining:
            candidate = ''.join(chosen)
            if best[0] is None or candidate < best[0]:
                best[0] = candidate
            return
        for i in range(idx_in_s, len(s)):                     # try every position for the next needed letter
            if s[i] in remaining:
                helper(i + 1, chosen + [s[i]], remaining - {s[i]})

    helper(0, [], set(distinct))
    return best[0]

