def remove_duplicate_letters(s):
    last = {c: i for i, c in enumerate(s)}                    # precompute last occurrence
    stack = []
    in_stack = set()
    for i, c in enumerate(s):
        if c in in_stack:
            continue                                            # already used, skip
        while stack and stack[-1] > c and last[stack[-1]] > i:    # safe to pop, reappears later
            in_stack.remove(stack.pop())
        stack.append(c)
        in_stack.add(c)
    return ''.join(stack)

