import java.util.*;

public class Main {
    static String removeDuplicateLetters(String s) {
        int[] last = new int[26];
        for (int i = 0; i < s.length(); i++) last[s.charAt(i) - 'a'] = i;   // precompute last occurrence
        Deque<Character> stack = new ArrayDeque<>();
        boolean[] inStack = new boolean[26];
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (inStack[c - 'a']) continue;                                 // already used, skip
            while (!stack.isEmpty() && stack.peek() > c && last[stack.peek() - 'a'] > i) {
                inStack[stack.pop() - 'a'] = false;                             // safe to pop, reappears later
            }
            stack.push(c);
            inStack[c - 'a'] = true;
        }
        StringBuilder sb = new StringBuilder();
        for (char c : stack) sb.append(c);
        return sb.reverse().toString();
    }
}

